const first = $input.first()?.json;
const pattern = Array.isArray(first) ? first[0] : first;
if (!pattern || !pattern.id) {
  return [{ json: { has_pattern: false, action: 'no_pattern', message: 'No content_patterns without variants.' } }];
}
return [{ json: { has_pattern: true, pattern } }];

const source = $('Code: build variant prompt').item.json;
const response = $input.first()?.json || {};
const raw = response.choices?.[0]?.message?.content || response.message?.content || response.content || '';
function arr(v) { return Array.isArray(v) ? v : (v == null || v === '' ? [] : [v]); }
function parse(text) {
  const clean = String(text || '').trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();
  try { return JSON.parse(clean); } catch (e) {}
  const start = clean.indexOf('{'); const end = clean.lastIndexOf('}');
  if (start >= 0 && end > start) return JSON.parse(clean.slice(start, end + 1));
  throw new Error('Model did not return parseable JSON');
}
let parsed;
try { parsed = parse(raw || JSON.stringify(response)); } catch (error) { return [{ json: { ok: false, error: error.message, raw_model_response: String(raw).slice(0, 2500) } }]; }
const recipeByGroup = new Map();
for (const r of source.recipes || []) {
  if (r.recipe_type === 'close_to_competitor') recipeByGroup.set('close', r.id);
  if (r.recipe_type === 'more_viral') recipeByGroup.set('viral', r.id);
  if (r.recipe_type === 'more_premium') recipeByGroup.set('premium', r.id);
  if (r.recipe_type === 'story') recipeByGroup.set('story', r.id);
}
const now = new Date().toISOString();
const rows = [];
function base(v, group, format, n) {
  return {
    batch_id: source.batch_id,
    pattern_recipe_id: recipeByGroup.get(group) || null,
    content_pattern_id: source.pattern_id,
    source_competitor_video_id: source.competitor_video_id,
    variant_group: group,
    variant_number: Number(n) || null,
    format,
    first_frame: String(v.first_frame || ''),
    hook_text: String(v.hook_text || ''),
    screen_text_json: arr(v.screen_text_json),
    scene_plan_json: arr(v.scene_plan_json),
    caption: String(v.caption || ''),
    cta: String(v.cta || ''),
    source_refs_json: [{ content_pattern_id: source.pattern_id, competitor_video_id: source.competitor_video_id }],
    borrowed_elements_json: arr(v.borrowed_elements_json),
    changed_elements_json: arr(v.changed_elements_json),
    forbidden_checks_json: arr(v.forbidden_checks_json),
    generation_model: 'openai/gpt-5.2',
    status: 'idea_created',
    created_at: now,
    updated_at: now
  };
}
for (const [idx, v] of arr(parsed.reels).entries()) {
  const g = ['close', 'viral', 'premium'].includes(v.group) ? v.group : (idx < 4 ? 'close' : idx < 8 ? 'viral' : 'premium');
  rows.push(base(v, g, 'reel', v.number || ((idx % 4) + 1)));
}
for (const [idx, v] of arr(parsed.stories).entries()) rows.push(base(v, 'story', 'story', v.number || idx + 1));
for (const [idx, v] of arr(parsed.captions).entries()) {
  const g = ['close', 'viral', 'premium'].includes(v.group) ? v.group : ['close', 'viral', 'premium'][idx % 3];
  rows.push(base({ ...v, first_frame: '', screen_text_json: [], scene_plan_json: [], borrowed_elements_json: [], changed_elements_json: [], forbidden_checks_json: [] }, g, 'caption', idx + 1));
}
return [{ json: { ok: true, pattern_id: source.pattern_id, row_count: rows.length, rows } }];

const inserted = $input.first()?.json;
const rows = Array.isArray(inserted) ? inserted : [inserted].filter(Boolean);
return [{ json: { action: 'variants_created', inserted_count: rows.length, message: `WF03 created ${rows.length} content_variants.` } }];
